import { HyperPbiStyleSystem, HyperPbiTheme } from "../schema/hyperpbiSchema";

export interface DesignPreset {
    id: string;
    name: string;
    summary: string;
    theme: HyperPbiTheme;
    styles: HyperPbiStyleSystem;
    guidance: { card: string; kpi: string; table: string; chart: string; controls: string; selected: string; spacing: string };
}

const preset = (id: string, name: string, summary: string, theme: HyperPbiTheme, globalCss: string, guidance: DesignPreset["guidance"]): DesignPreset => ({ id, name, summary, theme, styles: { globalCss, components: { "*": { style: { minWidth: 0 } }, table: { css: ".hp-table th{font-weight:700}.hp-table td{vertical-align:middle}" }, kpi: { css: ".hp-metric{min-height:72px}" } } }, guidance });

