export const designPresetNames = designPresets.map(presetItem => presetItem.name);
export const getDesignPreset = (nameOrId: string): DesignPreset => designPresets.find(item => item.name === nameOrId || item.id === nameOrId) ?? designPresets[0];
export const designPresetPrompt = (selected?: string): string => {
    const chosen = getDesignPreset(selected ?? "enterprise-light");
    return `Selected preset: ${chosen.name} — ${chosen.summary}\nUse these JSON-ready theme tokens: ${JSON.stringify(chosen.theme)}\nUse these reusable style rules as the starting point: ${JSON.stringify(chosen.styles)}\nCard: ${chosen.guidance.card}. KPI: ${chosen.guidance.kpi}. Table: ${chosen.guidance.table}. Chart: ${chosen.guidance.chart}. Controls: ${chosen.guidance.controls}. Selected state: ${chosen.guidance.selected}. Spacing: ${chosen.guidance.spacing}.`;
};
