import { ProviderConfiguration } from "./providerTypes";
import { EXTERNAL_PROVIDERS_AVAILABLE } from "./providerBuild";
export const coreProviderConfig:ProviderConfiguration={mode:"core",basemap:{provider:"none",enabled:false},geocoder:{provider:"none",enabled:false,autocomplete:false,userTriggeredOnly:true,cache:true,minScore:80},privacyAcknowledged:false};
export const mapsProviderConfig:ProviderConfiguration={mode:"maps",basemap:{provider:"osm",enabled:true,tileUrl:"https://tile.openstreetmap.org/{z}/{x}/{y}.png",attribution:"© OpenStreetMap contributors",maxZoom:19},geocoder:{provider:"none",enabled:false,autocomplete:false,userTriggeredOnly:true,cache:true,minScore:80},privacyAcknowledged:false};
export const defaultProviderConfig:ProviderConfiguration=EXTERNAL_PROVIDERS_AVAILABLE?mapsProviderConfig:coreProviderConfig;
export function validateProviderConfig(config?:ProviderConfiguration):string[]{const errors:string[]=[];if(config?.basemap?.enabled&&config.basemap.provider!=="none"&&!/^https:\/\//i.test(config.basemap.tileUrl??""))errors.push("Basemap tile URL must use HTTPS.");if(config?.geocoder?.enabled&&config.geocoder.provider!=="none"&&!/^https:\/\//i.test(config.geocoder.endpoint??""))errors.push("Geocoder endpoint must use HTTPS.");if((config?.geocoder?.rateLimitPerSecond??1)>1&&config?.geocoder?.provider==="nominatim")errors.push("Nominatim is limited to one request per second.");if(config?.geocoder?.autocomplete!==false)errors.push("Geocoder autocomplete is not supported.");if(config?.geocoder?.userTriggeredOnly!==true)errors.push("Geocoding must remain user-triggered.");return errors;}
