import { useState } from "preact/hooks";
import type { ComponentChildren } from "preact";
import { chartAppearanceProperties, chartAxisProperties, chartSeriesProperties, type ChartStyleProperty, type ChartStyle } from "../../components/charts/chartStyle";
import type { NormalizedField } from "../../data/normalizeData";
import { DraftInput } from "../map-studio/MapDraftInput";

type Json = Record<string, unknown>;
const record = (value: unknown): value is Json => !!value && typeof value === "object" && !Array.isArray(value);
const tabs = ["Data", "Series", "Axes", "Appearance", "Labels & Tooltips", "Interactions", "Advanced"];
const cartesian = new Set(["barChart","horizontalBarChart","lineChart","areaChart","scatterChart","comboChart","waterfallChart","heatmap","advancedChart"]);

function StyleControl({ property, value, change }: { property: ChartStyleProperty; value: unknown; change: (value: unknown) => void }) {
    const reset = <button type="button" class="hp-chart-reset" aria-label={`Reset ${property.label}`} disabled={value===undefined} onClick={()=>change(undefined)}>↺</button>;
    return <div class="hp-chart-property"><label><span>{property.label}</span>{property.type==="boolean"||property.type==="enum" ? <select aria-label={property.label} value={value===undefined?"":String(value)} onChange={event=>change(event.currentTarget.value===""?undefined:property.type==="boolean"?event.currentTarget.value==="true":event.currentTarget.value)}><option value="">Default</option>{(property.type==="boolean"?["true","false"]:property.options!).map(option=><option value={option}>{option==="true"?"On":option==="false"?"Off":option}</option>)}</select> : property.type==="number" ? <input type="number" aria-label={property.label} min={property.min} max={property.max} step={property.integer?1:property.key==="opacity"?0.05:"any"} value={value===undefined?"":String(value)} onChange={event=>change(event.currentTarget.value===""?undefined:Number(event.currentTarget.value))} /> : <DraftInput ariaLabel={property.label} value={typeof value==="string"?value:""} onCommit={value=>change(value||undefined)} />}</label>{reset}{property.help&&<small>{property.help}</small>}</div>;
}

export function ChartConfigurationPanel({ item, fields, onChange, onReplace, dataControls }: { item: Json; fields: Record<string,NormalizedField>; onChange: (property: string,value:unknown)=>boolean; onReplace:(changes:Json)=>boolean; dataControls:ComponentChildren }) {
    const [tab,setTab]=useState("Data"), [search,setSearch]=useState(""), [seriesIndex,setSeriesIndex]=useState(0), [axisKey,setAxisKey]=useState<"xAxis"|"yAxis">("yAxis"), [axisIndex,setAxisIndex]=useState(0);
    const style:ChartStyle=record(item.chartStyle)?item.chartStyle:{};
    const rawSeries=Array.isArray(item.series)?item.series as Json[]:[];
    const count=Math.max(1,rawSeries.length);
    const selectedIndex=Math.min(seriesIndex,count-1);
    const seriesType=item.type==="comboChart"?String(rawSeries[selectedIndex]?.chartType??"line"):String(item.type);
    const lineSeries=["line","lineChart","areaChart","radarChart"].includes(seriesType);
    const markerSeries=lineSeries||seriesType==="scatterChart";
    const stackSeries=["bar","barChart","horizontalBarChart","line","lineChart","areaChart"].includes(seriesType);
    const supportedSeriesProperties=chartSeriesProperties.filter(property=>!["smooth","step","lineWidth","dash"].includes(property.key)||lineSeries).filter(property=>!["symbol","symbolSize"].includes(property.key)||markerSeries).filter(property=>property.key!=="stack"||stackSeries).filter(property=>property.key!=="labelPosition"||["pieChart","donutChart","barChart","horizontalBarChart","lineChart","areaChart","comboChart"].includes(String(item.type))).map(property=>property.key==="labelPosition"?{...property,options:["pieChart","donutChart"].includes(String(item.type))?["inside","outside"]:["top","bottom","inside"]}:property);
    const seriesStyle=style.series?.[selectedIndex]??{};
    const axisStyle=style[axisKey]?.[axisIndex]??{};
    const numeric=Object.values(fields).filter(field=>field.dataType==="number"||field.type==="measure");
    const categories=Object.values(fields).filter(field=>field.dataType==="datetime"||field.type==="date"||field.dataType!=="number");
    const preferredCategory=categories.find(field=>field.type==="date"||field.dataType==="datetime")??categories[0];
    const update=(next:ChartStyle)=>onChange("chartStyle",JSON.parse(JSON.stringify(next)));
    const setSeriesStyle=(key:string,value:unknown)=>{const list=[...(style.series??[])];while(list.length<=selectedIndex)list.push({});list[selectedIndex]={...list[selectedIndex],[key]:value};update({...style,series:list});};
    const setAxis=(key:string,value:unknown)=>{const list=[...(style[axisKey]??[])];while(list.length<=axisIndex)list.push({});list[axisIndex]={...list[axisIndex],[key]:value};if(key==="domain"&&value==="fixed"){list[axisIndex].min??=0;list[axisIndex].max??=100;}update({...style,[axisKey]:list});};
    const matches=(property:ChartStyleProperty)=>!search||`${property.label} ${property.help??""}`.toLowerCase().includes(search.toLowerCase());
    const controls=(properties:ChartStyleProperty[], value:object, change:(key:string,value:unknown)=>void)=><div class="hp-chart-controls">{properties.filter(matches).map(property=><StyleControl key={property.key} property={property} value={(value as Json)[property.key]} change={value=>change(property.key,value)} />)}</div>;
    const changeSeries=(index:number,key:string,value:unknown)=>onChange("series",rawSeries.map((series,i)=>i===index?{...series,[key]:value}:series));
    const categoryAxis=String(item.type)!=="scatterChart"&&String(item.type)!=="advancedChart"&&(item.type==="horizontalBarChart"?axisKey==="yAxis":axisKey==="xAxis");
    const axisCount=axisKey==="yAxis"&&rawSeries.some(series=>series.axis==="right")?2:Array.isArray((record(item.options)?item.options:{})[axisKey])?((item.options as Json)[axisKey] as unknown[]).length:1;
    const rules=(kind:"referenceLines"|"referenceBands"|"thresholds")=>{
        const list=(seriesStyle[kind]??[]) as unknown as Json[];
        const label=kind==="referenceLines"?"Reference line":kind==="referenceBands"?"Reference band":"Threshold";
        const keys=kind==="referenceLines"?["value"]:kind==="referenceBands"?["from","to"]:["above"];
        return <details class="hp-chart-rule-editor"><summary>{label}s · {list.length}</summary>{list.map((rule,index)=><fieldset><legend>{label} {index+1}</legend>{controls([...keys.map(key=>({key,label:`${label} ${key}`,type:"number" as const})),{key:"label",label:`${label} label`,type:"text"},{key:"color",label:`${label} color`,type:"color"}],rule,(key,value)=>setSeriesStyle(kind,list.map((entry,i)=>i===index?{...entry,[key]:value}:entry)))}<button type="button" onClick={()=>setSeriesStyle(kind,list.filter((_,i)=>i!==index))}>Remove {label.toLowerCase()}</button></fieldset>)}<button type="button" disabled={list.length>=32} onClick={()=>setSeriesStyle(kind,[...list,kind==="referenceLines"?{value:0}:kind==="referenceBands"?{from:0,to:100}:{above:0,color:"#dc2626"}])}>Add {label.toLowerCase()}</button></details>;
    };
    return <section class="hp-chart-configuration" aria-label="Chart configuration"><header><strong>Chart configuration</strong><small>Changes use the shared preview and undo history.</small></header><nav aria-label="Chart categories">{tabs.map(label=><button type="button" aria-pressed={tab===label} disabled={label==="Axes"&&!cartesian.has(String(item.type))} onClick={()=>setTab(label)}>{label}</button>)}</nav><input type="search" aria-label="Search chart properties" placeholder="Find a setting…" value={search} onInput={event=>setSearch(event.currentTarget.value)} />
        {tab==="Data"&&<><div class="hp-inspector-control-grid">{dataControls}</div><details><summary>Suggested field mapping</summary><p>Suggestions preserve field semantics. Apply only after reviewing the columns and measures.</p><button type="button" disabled={!preferredCategory||!numeric[0]} onClick={()=>{if(item.type==="comboChart")onReplace({category:preferredCategory!.key,series:[{field:numeric[0].key,chartType:"line",aggregation:"sum"}]});else if(item.type==="scatterChart")onReplace({x:numeric[0].key,y:(numeric[1]??numeric[0]).key});else onReplace({category:preferredCategory!.key,measure:numeric[0].key});}}>Apply suggested fields</button></details><ul class="hp-chart-field-summary">{Object.values(fields).map(field=><li><strong>{field.displayName}</strong><code>{field.key}</code><small>{field.dataType??field.type} · {field.kind??(field.origin==="powerbi-measure"?"measure":"column")} · {field.origin??"received data"} · {field.queryAggregation??"not summarized"}{field.isImplicitAggregation?" (implicit)":""}</small></li>)}</ul></>}
        {(tab==="Series"||tab==="Labels & Tooltips")&&<><label>Active series<select aria-label="Active chart series" value={selectedIndex} onChange={event=>setSeriesIndex(Number(event.currentTarget.value))}>{Array.from({length:count},(_,index)=><option value={index}>{String(rawSeries[index]?.label??rawSeries[index]?.field??`Series ${index+1}`)}</option>)}</select></label>
            {tab==="Series"&&item.type==="comboChart"&&<fieldset><legend>Series binding</legend><label>Value field<select aria-label="Series value field" value={String(rawSeries[selectedIndex]?.field??"")} onChange={event=>changeSeries(selectedIndex,"field",event.currentTarget.value)}>{numeric.map(field=><option value={field.key}>{field.displayName} · {field.kind??"received numeric"}</option>)}</select></label><label>Series name<DraftInput ariaLabel="Series display name" value={String(rawSeries[selectedIndex]?.label??"")} onCommit={value=>changeSeries(selectedIndex,"label",value||undefined)} /></label><label>Chart type<select aria-label="Series chart type" value={String(rawSeries[selectedIndex]?.chartType??"line")} onChange={event=>changeSeries(selectedIndex,"chartType",event.currentTarget.value)}><option value="line">Line</option><option value="bar">Bar</option></select></label><label>Y axis<select aria-label="Series Y axis" value={String(rawSeries[selectedIndex]?.axis??"left")} onChange={event=>changeSeries(selectedIndex,"axis",event.currentTarget.value)}><option value="left">Left</option><option value="right">Right</option></select></label><label>Aggregation<select aria-label="Series aggregation" value={String(rawSeries[selectedIndex]?.aggregation??"sum")} onChange={event=>changeSeries(selectedIndex,"aggregation",event.currentTarget.value)}>{["sum","avg","min","max","count","distinctCount"].map(value=><option value={value}>{value}</option>)}</select></label><button type="button" disabled={rawSeries.length<2} onClick={()=>onChange("series",rawSeries.filter((_,index)=>index!==selectedIndex))}>Remove series</button><button type="button" onClick={()=>{if(numeric.length&&onChange("series",[...rawSeries,{field:(numeric.find(field=>!rawSeries.some(series=>series.field===field.key))??numeric[0]).key,chartType:"line",aggregation:"sum"}]))setSeriesIndex(rawSeries.length);}}>Add series</button></fieldset>}
            {controls(supportedSeriesProperties.filter(property=>tab==="Labels & Tooltips"?["labels","labelPosition","decimals"].includes(property.key):!["labels","labelPosition","decimals"].includes(property.key)),seriesStyle,setSeriesStyle)}
            {tab==="Series"&&cartesian.has(String(item.type))&&<>{rules("referenceLines")}{rules("referenceBands")}{rules("thresholds")}</>}
            {tab==="Labels & Tooltips"&&controls(chartAppearanceProperties.filter(property=>property.key.startsWith("tooltip")),style,(key,value)=>update({...style,[key]:value}))}
        </>}
        {tab==="Axes"&&<><label>Axis<select aria-label="Chart axis" value={`${axisKey}:${axisIndex}`} onChange={event=>{const [key,index]=event.currentTarget.value.split(":");setAxisKey(key as "xAxis"|"yAxis");setAxisIndex(Number(index));}}>{["xAxis","yAxis"].flatMap(key=>Array.from({length:key===axisKey?axisCount:key==="yAxis"&&rawSeries.some(series=>series.axis==="right")?2:1},(_,index)=><option value={`${key}:${index}`}>{key==="xAxis"?"X":"Y"} axis {index+1}{key==="yAxis"?(index===0?" · left":" · right"):""}</option>))}</select></label>{controls(chartAxisProperties.filter(property=>!categoryAxis||!["domain","min","max","logarithmic","decimals"].includes(property.key)).filter(property=>!["min","max"].includes(property.key)||axisStyle.domain==="fixed"),axisStyle,setAxis)}</>}
        {tab==="Appearance"&&controls(chartAppearanceProperties.filter(property=>!property.key.startsWith("tooltip")&&!["zoom","animation","animationDuration"].includes(property.key)),style,(key,value)=>update({...style,[key]:value}))}
        {tab==="Interactions"&&<>{controls(chartAppearanceProperties.filter(property=>property.key==="zoom"),style,(key,value)=>update({...style,[key]:value}))}<p>Feature clicks use the component's existing interaction policy and valid Power BI row identities. Zoom changes preserve the current view without creating model relationships.</p></>}
        {tab==="Advanced"&&<>{controls(chartAppearanceProperties.filter(property=>["animation","animationDuration"].includes(property.key)),style,(key,value)=>update({...style,[key]:value}))}<button type="button" onClick={()=>onChange("chartStyle",undefined)}>Reset chart presentation</button><p>The existing Structured JSON section accepts validated declarative ECharts options. Functions, callbacks, external resources and unknown option keys are rejected.</p></>}
    </section>;
}
