export function AiPromptPreview({ prompt, onCopy, onDownload }: { prompt: string; onCopy: () => void; onDownload: () => void }) { return <section class="hp-ai-preview"><header><strong>Generated prompt</strong><div><button onClick={onCopy}>Copy prompt</button><button onClick={onDownload}>Download</button></div></header><textarea readOnly value={prompt} aria-label="Generated AI prompt" /></section>; }
